Была задача и всё. Ничего кроме задачи не спрашивали: Вот вся задача с моим решением. надо написать класс АТМ: # Банкомат, который заряжается кассетами с купюрами, с нашим приложением на борту
# должен уметь выдавать купюры для заданной суммы или отвечать отказом
# При выдаче купюры списываются с баланса банкомата.
# Допустимые номиналы: 50₽, 100₽, 500₽, 1000₽, 5000₽.

# 7400
#
# 5000 1
#
# 1000 1
#
# 100 4


class ATM:
    def __init__(self, sdk: "SDK"):
        self.accept_nominals = sorted([50, 100, 500, 1000, 5000], reverse=True)
        self.sdk = sdk
        self.count_nominal_banknotes = {}
        for nominal in self.accept_nominals:
            self.count_nominal_banknotes[nominal] = self.sdk.count_banknotes(nominal)
    def out_banknotes(self, sum_money: int):


        self._is_possible_out(sum_money)

        banknotes = self._counting_banknotes(sum_money)

        for banknote, count in banknotes.items():
            self.sdk.move_banknote_to_dispenser(banknote, count)

        self.sdk.open_dispenser()

        self._update_count_banknotes(banknotes)

        return banknotes


    def _counting_banknotes(self, sum_money: int) -> dict[int, int]:

        result = {}

        for nominal in self.accept_nominals:
            count_in_bankomat = self.count_nominal_banknotes[nominal]
            if sum_money < nominal:
                continue

            count_nominal = sum_money // nominal

            if count_nominal > count_in_bankomat:
                count_nominal = count_in_bankomat

            sum_money = sum_money - nominal * count_nominal

            result[nominal] = count_nominal

        if sum_money > 0:
            raise ValueError("Не можем выдать данную сумму")
        return result

    def _is_possible_out(self, sum_money: int):
        total_money = 0
        for nominal, count in self.count_nominal_banknotes.items():
            total_money += count * nominal
        if total_money < sum_money:
            raise ValueError("В банкомате недостаточно средств")

        if sum_money <= 0:
            raise ValueError("Неверная сумма")


    def _update_count_banknotes(self, out_banknotes: dict[int, int]) -> None:
        for banknote, count in out_banknotes.items():
            self.count_nominal_banknotes[banknote] -= count

# Устройство банкомата:
# - деньги расположены в кассетах внутри банкомата, которые загружает инкассатор и перезагружает банкомат;
