# n => [1...n]
# i % 3 => Fizz
# i % 5 => Buzz
# i % 3,5 => FizzBuzz

def foo(n: int) -> str:
    for i in range(1, n+1):
        if i % 3 == 0 and i % 5 == 0:
            print('FizzBuzz')
        elif i % 3 == 0:
            print('Fizz')
        elif i % 5 == 0:
            print('Buzz')
        else:
            print(i)


