import pytest  
def dict_diff(old, new):  
    # Внутренняя функция для превращения словаря в плоский список  
    def flatten(d, parent_key=''):  
        items = []  
        for k, v in d.items():  
            # Создаем полный путь ключа, соединяя через точку  
            full_key = f"{parent_key}.{k}" if parent_key else k  
            if isinstance(v, dict):  
                # Если встретили словарь — уходим в рекурсию  
                items.extend(flatten(v, full_key))  
            else:  
                # Если это значение — сохраняем кортеж (ключ, значение)  
                items.append((full_key, v))  
        return items  

    # Получаем плоские структуры для обоих словарей  
    old_flat = flatten(old)  
    new_flat = flatten(new)  

    diff = []  

    # 1. Проверяем, что исчезло из старого или изменилось  
    for item in old_flat:  
        if item not in new_flat:  
            # item[0] - это ключ, item[1] - это значение  
            diff.append(f"- {item[0]} {item[1]}")  

    # 2. Проверяем, что появилось в новом или обновилось  
    for item in new_flat:  
        if item not in old_flat:  
            diff.append(f"+ {item[0]} {item[1]}")  

    return "\n".join(diff)  




def test_empty_dicts():  
    assert dict_diff({}, {}) == ""  

def test_no_changes():  
    d = {'a': 1, 'b': {'c': 2}}  
    assert dict_diff(d, d) == ""  

def test_value_change():  
    old = {'a': 1}  
    new = {'a': 2}  
    result = dict_diff(old, new)  
    assert "- a 1" in result  
    assert "+ a 2" in result  

def test_nested_addition():  
    old = {'a': 1}  
    new = {'a': 1, 'b': {'c': 3}}  
    assert "+ b.c 3" in dict_diff(old, new)

