по задачам тут:

1. Дана строка из букв и знаков препинания. Проверить, является ли строка палиндромом. Знаки препинания на "свойство палиндромности" не влияют.
# "А роза упала на лапу Азора." -> True
# "./:!  ca,.,.!@c" -> True
# isalpha()
# "!.." -> True

def is_palindrome(s):
#     clean = ''.join(i.lower() for i in s if i.isalpha())
#     return clean == clean[::-1]
    left, right = 0, len(s) - 1
    while left < right:
        while left < right and not s[left].isalpha():     
            left += 1
        while left < right and not s[right].isalpha():
            right -= 1
        if s[left].lower() != s[right].lower():
            return False
        left += 1
        right -= 1
    return True


2. Найти пару чисел, которые в сумме дают фиксированное значение, и вывести их индексы. nums: list[int], target: int
# (nums=[2, 1, 3], target=4) -> (1, 2)
def two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        complete = target - num
        if complete in seen:
            return(seen[complete], i)
        seen[num] = i

    return None


