import uuid

from fastapi import APIRouter
from fastapi.params import Depends
from pydantic import BaseModel
from sqlalchemy.sql.annotation import Annotated


class UserModel(BaseModel):

    id: uuid.UUID
    name: str


async def get_from_db(user_id: uuid.UUID) -> UserModel:
    # async request to db
    return UserModel(id=user_id)


async def get_user_model(user_id: uuid.UUID) -> UserModel:
    return await get_from_db(user_id)


router = APIRouter()


@router.get('/get_user_name')
def get_user_name(user: Annotated[UserModel, Depends(get_user_model)]) -> str:
    return user.name

# Написать функцию, которая возьмет значение по пути во вложенном словаре
from typing import Any, Optional


def get_by_path(obj: dict[str, Any], path: str) -> Optional[Any]:
    keys = path.split('.')

    for key in keys:
        if key in obj and isinstance(obj, dict):
            obj = obj[key]
        else:
            return None
    return obj


obj = {
    'a': {
        'b': {
            'c': 1
        }
    }
}
print(get_by_path(obj, 'a.b.c')) # 1
print(get_by_path(obj, 'a.d.e')) # None

Сначала позадавал вопросы про опыт, все базово. Потом сказал вспомнить самую сложную или просто интересную задачу, которую в последний год удалось реализовать. Сказал что спрашивает из за того, что "Очень много накрутчиков опыта, которые не могут ответить на такие базовые вопросы". Дальше по техничке были в основном задачи, приложу ниже.
1. Задача найти n-ое число фибоначи + тесты на pytest.
2. Написать свой контекстный менеджер по типу pytest.raises
3. Задачка на сырой запрос SQL. Дана таблица логов с уникальной датой как PK и количеством инвентаря. Нужно написать оконную функцию для поиска суммы кол-ва инвентаря по датам.

# Фибоначчи
# 1 1 2 3 5 8
# f(n) = f(n-1) + f(n-2)

import pytest

def fibonacci(n):
    if n <= 0:
        raise ValueError("Error")

    if n == 1 or n == 2:
        return 1

    prev, curr = 1, 1

    for _ in range(3, n + 1):
        prev, curr = curr, prev + curr
    return curr

@pytest.mark.parametrize(
    "n, expected",
    [
        (1, 1),
        (2, 1),
        (6, 9),
        (10, 55)
        ])    
def test_fibonacci_valid(n, expected):
    assert fibonacci(n) == expected

