# Банкомат.
# Инициализируется набором купюр и умеет выдавать купюры для заданной суммы, либо отвечать отказом.
# При выдаче купюры списываются с баланса банкомата.
# Допустимые номиналы: 50₽, 100₽, 500₽, 1000₽, 5000₽.
class ATM:
    def init(self, sdk):  # место для кода
        self._sdk = sdk

    def dispenser_cash(self, amount):
        banknotes_distrib = self.calc_banknotes_distrib(self._sdk, amount)
        for banknote, count in banknotes_distrib.items():
            self._sdk.move_banknote_to_dispenser(banknote, count)
        self._sdk.open_dispenser()


    def calc_banknotes_distrib(self, amount):
        'Подсчет комбинаций купюр'
        denoms = self._sdk.get_available_denom() #5000, 1000, 100 ...
        current_amount = amount # 5100, 100
        banknotes_distrib = {} #5000
        for denom in denoms:
            count = current_amount // denom #1, 0
            availab_count = self._sdk.count_banknotes(denom) #100
            count = min(count, availab_count)

            if count > 0:
                banknotes_distrib[denom] = count
                current_amount -= count * denom

            if current_amount == 0:
                break

        if current_amount > 0:
            print('Запрашиваемую сумму невозможно выдать')
            return {}

        return banknotes_distrib

