# Банкомат.
# Инициализируется набором купюр и умеет выдавать купюры для заданной суммы, либо отвечать отказом.
# При выдаче купюры списываются с баланса банкомата.
# Допустимые номиналы: 50₽, 100₽, 500₽, 1000₽, 5000₽.

class ATMException(Exception):
    pass

class ATM:
    def init(self, sdk: SDK):
        self._sdk = sdk
        self.cache = {5000: 0, 1000: 0, 500: 0,
                      100: 0, 50: 0}
        self.fill_cache()

    def __fill_cache(self)-> None:
        for k in self.cache:
            self.cache[k] = self._sdk.count_banknotes(k)

    def _validate_cache(self, banknotes: dict) -> None:
        for k, v in banknotes.items():
            self.cache[k] -= v

    def _split_amount(self, summ: int)-> dict:
        result = {}
        for k, v in self.cache.items():
            count = summ//k
            if count <= v:
                summ%=k
                result[k] = count
            else:
                summ -= k*v
                result[k] = v
        if summ != 0:
            raise ATMException
        return result

    def _move_banknotes(self, banknotes: dict) -> None:
        for k, v in banknotes.items():
            if v == 0:
                continue
            self._sdk.move_banknote_to_dispenser(k, v)


    def dispense_banknbotes(self, summ: int) -> str:
        try:
            res = self._split_amount(summ)
        except ATMException:
            banknotes = [k for k,v in self.cache.items() if v != 0]
            max_summ = 0
            for k, v in self.cache.items():
                max_summ += k*v
            return f"Доступный банкноты {banknotes}\nМаксимальная сумма к выдаче: {max_summ}"
        self._validate_cache(res)
        self._move_banknotes(res)
        self._sdk.open_dispenser()
        return ""

class SDKMock(SDK):
