class Queue:
    def init(self):
        self.stack1 = []
        self.stack2 = []

    def pop(self):
        if not self.stack1 and not self.stack2:
            raise ValueError
        if not self.stack2:
            for i in self.stack1[::-1]:
                self.stack2.append(i)
            self.stack1.clear()
        return self.stack2.pop()

    def append(self, item):
        self.stack1.append(item)


