def max_prefix_len(list_str: List[str]) -> str:
    res = list_str[0]
    for i in list_str:
        for indx, j in enumerate(res):
            if len(i)-1 >= indx and i[indx] == j:
                continue
            else:
                res = res[:indx]
                break    
