def pascal_triangle(numRow: int):
    output = [[1]]
    for i in range(1, numRow):
        output.append(next_layer(output[-1]))
    return output


def next_layer(list_layer: list):
    result = []
    for i in range(len(list_layer)-1):
        result.append(list_layer[i]+list_layer[i+1])
    return [1, *result, 1]


