def is_monotone(slice: list) -> bool:
    inc, dec = True
    for i in range(1, len(slice)):
        if slice[i] < slice[i-1]:
            inc = False
        if slice[i] > slice[i-1]:
            dec = False

    return inc or dec

def rle_encode(text: str) -> str:
    if len(text) <= 1:
        return text

    result = []
    count = 1
    for i in range(1, len(text)):
        if text[i] == text[i-1]:
            count += 1
        else:
            result.append(text[i-1], count)
            count = 1
    return "".join(result)

