python
def segment(lst, x):
    n = 0
    n2 = 0
    flag = 0
    if len(lst) == 0:
        return -1
    for i in lst:
        if i >= x:
            n2 += 1
        elif i == x:
            n2 += 1
            flag = 1
        if i < x:
            if n2 > n and flag == 1:
                n = n2
            n2 = 0
            flag = 0
    if n2 > n and flag == 1:
        n = n2
    if n != 0:
        return n
    else:
        return -1

