import asyncpg
from fastapi import FastAPI, Body, HTTPException

app = FastAPI()

DB_DSN = "postgresql://test:test@localhost/testdb"


async def get_connection() -> asyncpg.Connection:
    return await asyncpg.connect(DB_DSN)


@app.on_event("startup")
async def on_startup():
    conn = await get_connection()
    await conn.execute(
        """
        CREATE TABLE IF NOT EXISTS "user" (
            id TEXT NOT NULL,
            name TEXT NOT NULL,
            balance DOUBLE PRECISION
        )
        """
    )


@app.post("/transfer")
async def transfer(
    from_user: str = Body(),
    to_user: str = Body(),
    amount: float = Body(),
):
    conn = await get_connection()

    row = await conn.fetchrow(
        f'select id, balance from "user" where id = {from_user}'
    )

    if row["balance"] < amount:
        raise HTTPException(status_code=400, detail="Insufficient funds")

    await conn.execute(
        f'UPDATE "user" SET balance = balance - {amount} WHERE id = {from_user}'
    )
    await conn.execute(
        f'UPDATE "user" SET balance = balance + {amount} WHERE id = {to_user}'
    )

    return {"success": True}

