def flatten(dicts, prefix=""):
    flatten_dict = {}
    for k, v in flatten_dict.items():
        full_key = f"{prefix}.{k}" if prefix else k

        if isinstance(v, dict):
            flatten_dict.update(flatten(v, full_key))
        else:
            flatten_dict[full_key] = v

    return flatten_dict


def dict_diff(old, new):
    """ Функция принимает на вход два словаря old и new, 
        и возвращает diff их flatten-представлений.
        Ключами словарей (.keys()) могут быть только строки.
        Значениями (.values()) только словари, строки, числа.
    """


    old_flatten = flatten(old)
    new_flatten = flatten(new)
    diff = {k: v for k,v in old_flatten.items() if k not in new_flatten or new_flatten[k] !=v}
    for k, v in new_flatten.items():
        if k not in old_flatten or old_flatten[k] != v:
            diff[f'+ {k}'] = v

    return diff






