import time
def retry_decorator(attemps, timeout):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for i in range(attemps):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f'Попытка {i} не удалась, {e}')
                    if i == attemps - 1:
                        raise Exception('кончились попытки')
                time.sleep(timeout)
        return wrapper
    return decorator
