Код для лайфкодинга. 


class User:
    def __init__(self, name, tags=[]):
        self.name = name
        self.tags = tags

    def add_tag(self, tag):
        if tag:
            self.tags.append(tag)


def get_active_users(users):
    result = []
    for user in users:
        if user.name is "":
            continue

        if len(user.tags) > 0 is True:
            result.append(user)
    return result


def remove_empty_tags(user):
    for tag in user.tags:
        if tag == "":
            user.tags.remove(tag)


def sort_users(users):
    return users.sort(key=lambda x: x.name)


def main():
    users = [
        User("Alice", ["python", "J"]),
        User("Bob"),
        User("dev")
    ]

    for user in users:
        remove_empty_tags(user)

    active_users = get_active_users(users)
    sorted_users = sort_users(active_users)

    for user in sorted_users:
        print(user.name, user.tags)


if __name__ == "__main__":
    main()

Тут надо написать декоратор к функциям.

import time

def get_users():
    print("start get_users")
    started = time.time()

    data = ["alice", "bob", "charlie"]
    time.sleep(0.1)

    finished = time.time()
    print("result:", data)
    print("elapsed:", finished - started)
    print("end get_users")
    return data

def get_orders():
    print("start get_orders")
    started = time.time()

    data = [1, 2, 3]
    time.sleep(0.2)

    finished = time.time()
    print("result:", data)
    print("elapsed:", finished - started)
    print("end get_orders")
    return data

def get_report():
    print("start get_report")
    started = time.time()

    data = {"users": 3, "orders": 3}
    time.sleep(0.15)

    finished = time.time()
    print("result:", data)
    print("elapsed:", finished - started)
    print("end get_report")
    return data

def main():
    get_users()
    get_orders()
    get_report()

if __name__ == "__main__":
    main()

Провести ревью, посмотреть обработку ошибок.

def to_int(value):
    try:
        return int(value)
    except:
        return 0

def get_discount(user):
    try:
        return user["discount"]
    except Exception:
        return None

def calculate_total(order, user):
    try:
        price = to_int(order["price"])
        qty = to_int(order.get("qty", 1))
        discount = get_discount(user)

        total = price * qty

        if discount:
            total = total - discount

        return total
    except KeyError:
        print("Missing key")
    except:
        print("calculation error")
        return 0

def main():
    orders = [
        {"price": "100", "qty": "2"},
        {"price": None, "qty": 3},
        {"qty": 1},
    ]

    user = {"discount": "10"}

    for order in orders:
        result = calculate_total(order, user)
        print(result)

if __name__ == "__main__":
    main()
